import React from 'react';
import { Center, Stack } from '@fiverr-private/layout_components';
import { PlusIcon } from '@fiverr-private/visuals';
import { I18n } from '@fiverr-private/i18n-react';
import ComboboxOptionLabel from '../ComboboxOption/ComboboxOptionLabel';
import ComboboxOption from '../ComboboxOption';
import useComboboxContext from '../hooks/useComboboxContext';
import { getOptionText } from '../utils';

const ComboboxOptionCreate = ({ onOptionCreated }: { onOptionCreated?: (option: string) => void }) => {
  const { searchValue, filteredMenuGroups } = useComboboxContext();
  const items = React.Children.toArray(filteredMenuGroups)
    ?.flat()
    .map((item) => getOptionText(item));
  const exists = items.some((item) => item.toLowerCase() === searchValue?.toLowerCase());

  return searchValue && !exists ? (
    <ComboboxOption
      dataTrackTag="combobox_option_create"
      value={searchValue}
      onClick={() => onOptionCreated?.(searchValue)}
    >
      <Stack alignItems="center" gap="1">
        <Center padding="2">
          <PlusIcon />
        </Center>
        <I18n k="forms.combobox.comboboxOptionCreate.add" />
        <ComboboxOptionLabel isOptionCreate>{searchValue}</ComboboxOptionLabel>
      </Stack>
    </ComboboxOption>
  ) : null;
};

ComboboxOptionCreate.displayName = 'ComboboxOptionCreate';
ComboboxOptionCreate.id = 'ComboboxOptionCreate';
export default ComboboxOptionCreate;
