import React from 'react';
import { MenuGroup } from '@fiverr-private/dropdown';
import useComboboxContext from '../hooks/useComboboxContext';
import VirtualList from './VirtualList';
import type { ComboboxOptionGroupProps } from './types';

const ComboboxOptionGroup = ({
  children,
  isMulti,
  label,
  name,
  dataTrackTag = 'combobox_option_group',
  dataTrackValue = name,
}: ComboboxOptionGroupProps) => {
  const { hasMultipleGroups } = useComboboxContext();
  const shouldRenderVirtualList = React.Children.toArray(children).length > 100 && !hasMultipleGroups;

  return (
    <MenuGroup
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      name={name}
      label={label}
      isMulti={isMulti}
      hideSelectedIndicator={isMulti}
    >
      {shouldRenderVirtualList ? <VirtualList>{children}</VirtualList> : children}
    </MenuGroup>
  );
};

ComboboxOptionGroup.id = MenuGroup.id;
export default ComboboxOptionGroup;
