import React, { ReactElement, useCallback, useRef, useEffect } from 'react';
import { VariableSizeList } from 'react-window';
import { useIntersectionObserver } from '@fiverr-private/hooks';
import { MenuGroup } from '@fiverr-private/dropdown';
import ListRow from '../ListRow';

const VirtualList = ({ children }: { children: React.ComponentProps<typeof MenuGroup>['children'] }) => {
  const listContainerRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<VariableSizeList>(null);
  const items = React.Children.toArray(children) as ReactElement[];
  const entry = useIntersectionObserver(listContainerRef, { threshold: 0 });
  const isVisible = Boolean(entry?.isIntersecting);
  const rowHeights = useRef({});
  const getRowHeight = (index) => rowHeights.current[index] || 50;
  const setRowHeight = useCallback(
    (index: number, size: number) => {
      rowHeights.current = { ...rowHeights.current, [index]: size };
      listRef?.current?.resetAfterIndex(index);
    },
    [listRef]
  );

  useEffect(() => {
    listRef?.current?.scrollToItem(0);
  }, [children, listRef]);

  return (
    <div ref={listContainerRef}>
      <VariableSizeList
        ref={listRef}
        height={200}
        width="100%"
        itemSize={getRowHeight}
        itemCount={items.length}
        itemData={items}
      >
        {({ style, ...props }) => (
          <div style={style}>
            <ListRow isVisible={isVisible} setRowHeight={setRowHeight} {...props} />
          </div>
        )}
      </VariableSizeList>
    </div>
  );
};

VirtualList.displayName = 'VirtualList';
export default VirtualList;
