import React, { useEffect, useRef } from 'react';
import { useElementSize } from '@fiverr-private/hooks';
import { ListRowProps } from './types';

const ListRow = ({ data, index, setRowHeight, isVisible }: ListRowProps) => {
  const rowRef = useRef<HTMLDivElement>(null);
  const { width: elementWidth, height: elementHeight } = useElementSize(rowRef.current);

  useEffect(() => {
    if (rowRef.current) {
      setRowHeight(index, elementHeight);
    }
  }, [rowRef, elementWidth, setRowHeight, index, elementHeight, isVisible]);

  return isVisible ? <div ref={rowRef}>{data[index]}</div> : null;
};

export default ListRow;
